contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(depositAmount > 0);

        // Give c some Ether and record a balance for this test contract.
        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 priorBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 priorContractEth = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractEth = address(c).balance;

        assert(!reverted && afterBalance == 0 && priorContractEth >= priorBalance && afterContractEth == priorContractEth - priorBalance);
    }

    receive() external payable {}
}

