// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        try c.addToBalance{value: depositAmount}() {} catch { return; }
        uint256 priorBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { priorBalance = __r; } catch { return; }
        uint256 priorContractEth = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint256 afterContractEth = address(c).balance;
        assertTrue(!reverted && afterBalance == 0 && priorContractEth >= priorBalance && afterContractEth == priorContractEth - priorBalance);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
